const logs = [];

// Generate 42 auth.log-style sample lines.
// All IPs are documentation-only example addresses.
const attackers = [
  { ip: "192.0.2.10", count: 12, users: ["root", "admin", "ubuntu", "test", "oracle", "deploy"] },
  { ip: "198.51.100.20", count: 11, users: ["admin", "guest", "test", "backup", "user"] },
  { ip: "203.0.113.30", count: 8, users: ["root"] },
  { ip: "203.0.113.40", count: 4, users: ["deploy"] },
  { ip: "192.0.2.60", count: 5, users: ["guest", "test"] },
  { ip: "192.0.2.70", count: 2, users: ["guest"] }
];

let id = 1000;
let minute = 0;

// Generate failed SSH login lines.
for (const attacker of attackers) {
  for (let i = 0; i < attacker.count; i++) {
    const user = attacker.users[i % attacker.users.length];
    const time = `10:${String(minute).padStart(2, "0")}:${String(i + 1).padStart(2, "0")}`;

    logs.push(
      `Oct 13 ${time} server sshd[${++id}]: Failed password for ${user} from ${attacker.ip} port ${41000 + id} ssh2`
    );
  }
  minute++;
}

// Add two successful login lines.
// Total: 40 failed attempts + 2 successes = 42 raw log lines.
logs.push(
  "Oct 13 10:06:01 server sshd[2001]: Accepted publickey for sysadmin from 192.0.2.50 port 45001 ssh2"
);
logs.push(
  "Oct 13 10:06:02 server sshd[2002]: Accepted publickey for deploy from 192.0.2.50 port 45002 ssh2"
);

// Count failed logins per IP address.
const counts = {};

for (const line of logs) {
  if (!/Failed password for /.test(line)) continue;

  const match = line.match(/\bfrom\s+(\d{1,3}(?:\.\d{1,3}){3})\b/);
  if (!match) continue;

  const ip = match[1];
  counts[ip] = (counts[ip] || 0) + 1;
}

// Return one summary item per IP.
// RED: 6 or more failures.
// ORANGE: 3–5 failures.
// GREEN: fewer than 3 failures.
return Object.entries(counts).map(([ip, failures]) => ({
  json: {
    tag: "NGP-034",
    ip,
    failures,
    threshold: 6,
    flagged: failures >= 6,
    severity: failures >= 6
      ? "red"
      : failures >= 3
        ? "orange"
        : "green"
  }
}));

return $input.all().map(item => {
  const d = item.json;
  const parts = d.ip.split(".");

  return {
    json: {
      tag: d.tag,
      ipMasked: `${parts[0]}.${parts[1]}.${parts[2]}.xxx`,
      failures: d.failures,
      threshold: d.threshold,
      flagged: d.flagged,
      severity: d.severity
    }
  };
});

const aiItems = $input.all();
const sourceItems = $('Mask IP for AI').all();

return aiItems.map((item, index) => {
  const source = sourceItems[index]?.json ?? {};

  let ai = {};
  const raw = item.json.output;

  try {
    ai = typeof raw === 'string' ? JSON.parse(raw) : (raw ?? {});
  } catch (e) {
    ai = {};
  }

  return {
    json: {
      ...source,
      verdict: ai.verdict ?? 'inconclusive',
      recommendation: ai.recommendation ?? 'monitor',
      reason: ai.reason ?? 'No valid AI reason returned',
      severity: source.severity ?? 'green',
    },
  };
});
